import React, { useEffect, useState } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [user, setUser] = useState(null);
  const [repos, setRepos] = useState([]);
  const [autoReviewMap, setAutoReviewMap] = useState({});

  useEffect(() => {
    axios.get('http://localhost:5000/api/user', { withCredentials: true })
      .then((res) => setUser(res.data.user));
  }, []);

  useEffect(() => {
    axios.get('http://localhost:5000/api/github/repos', { withCredentials: true })
      .then((res) => {
        setRepos(res.data);

        // Optional: You can fetch saved autoReview from server here and set map
        // Skipping for simplicity, you can manually turn ON/OFF and it gets saved
      });

       useEffect(() => {
  axios.get('http://localhost:5000/api/gitlab/repos', { withCredentials: true })
    .then((res) => {
      console.log("GitLab repos:", res.data);
      // you can show them if user logged in with GitLab
    })
    .catch((err) => console.log("No GitLab repos or not a GitLab user"));
}, []);

       axios.get('http://localhost:5000/api/repo/auto-review', { withCredentials: true })
    .then((res) => {
      setAutoReviewMap(res.data); // { repoName: true/false }
    });

  }, []);


  
  const toggleAutoReview = (repoName, currentStatus) => {
    const newStatus = !currentStatus;

    axios.post('http://localhost:5000/api/repo/auto-review', {
      repoName,
      provider: 'github',  // or 'gitlab'
      autoReview: newStatus
    }, { withCredentials: true })
      .then(() => {
        setAutoReviewMap(prev => ({ ...prev, [repoName]: newStatus }));
      });
  };

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Welcome, {user?.displayName || 'Loading...'}</h2>

      <h3>Your Repositories</h3>
      <ul>
        {repos.map((repo) => (
          <li key={repo.name}>
            <strong>{repo.name}</strong> | ⭐ {repo.stars} | Branch: {repo.default_branch}
            <button style={{ marginLeft: '1rem' }} onClick={() => toggleAutoReview(repo.name, autoReviewMap[repo.name])}>
              {autoReviewMap[repo.name] ? 'Disable Auto Review' : 'Enable Auto Review'}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Dashboard;
